    private static int feedbackAdjustmentRate = 10; // Adjust difficulty every X attempts
    private static int maxTemperature = 80; // Simulated max temperature for the system
    private static Random rng = new Random();

    public static void Main(string[] args)
    {
        string data = "Quantum-encrypted mining data"; // Data to mine
        Console.WriteLine("Starting Mark1 Bitcoin Miner...");
        MineBitcoin(data);
    }

