    {
        int nonce = 0;

        while (true)
        {
            // Loop 1: Input Perturbation
            string perturbedData = PerturbInput(baseData, nonce);

            // Compute the hash
            string hash = ComputeSHA256Hash(perturbedData);

            // Loop 2: Hash Harmonic Analysis
            double hashHarmonic = AnalyzeHashHarmonic(hash);

            // Loop 3: Output Adjustment based on harmonic
            nonce = AdjustNonceBasedOnHarmonic(nonce, hashHarmonic);

            // Check if the hash meets difficulty criteria
            if (hash.StartsWith(new string('0', difficulty)))
            {
                Console.WriteLine($"Hash found: {hash} with nonce: {nonce}");
                Console.WriteLine($"Harmonic Value: {hashHarmonic}");
                break;
            }

            nonce++;
        }
    }

    // Loop 1: Input Perturbation
    private static string PerturbInput(string data, int nonce)
    {
        // Introduce randomness and perturbation into the input
        int randomPerturbation = rng.Next(0, 1000000);
        return $"{data}-{nonce}-{randomPerturbation}";
    }

    // Loop 2: Hash Harmonic Analysis
    private static double AnalyzeHashHarmonic(string hash)
    {
        // Calculate the harmonic resonance of the hash (e.g., sum of hash byte values)
        double harmonicSum = 0;

        foreach (char c in hash)
        {
            harmonicSum += c;
        }

        // Normalize the harmonic value
        return harmonicSum / hash.Length;
    }

    // Loop 3: Output Adjustment
    private static int AdjustNonceBasedOnHarmonic(int nonce, double hashHarmonic)
    {
        // Dynamically adjust the nonce increment based on the harmonic
        if (hashHarmonic < 50)
        {
            nonce += 2; // Increase exploration
        }
        else if (hashHarmonic > 100)
        {
            nonce -= 1; // Slow down to refine
        }

        return nonce;
    }

    // SHA-256 hash computation
    private static string ComputeSHA256Hash(string input)
    {
        using (SHA256 sha256 = SHA256.Create())
        {
            byte[] hashBytes = sha256.ComputeHash(Encoding.UTF8.GetBytes(input));
            StringBuilder hash = new StringBuilder();

            foreach (byte b in hashBytes)
            {
                hash.Append(b.ToString("x2"));
            }

            return hash.ToString();
        }
    }
}
