using System;
using System.Net.Http;
using System.Security.Cryptography;
using System.Text;
using Newtonsoft.Json.Linq;

class Mark1HarmonicBitcoinMiner
{
    private static string apiUrl = "https://api.blockcypher.com/v1/btc/main";
    private static int nonce = 0;

    public static async System.Threading.Tasks.Task Main(string[] args)
    {
        Console.WriteLine("Fetching real blockchain data from API...");
        var blockData = await FetchBlockDataFromAPI();

        if (blockData != null)
        {
            Console.WriteLine("Starting Mark1 Harmonic Miner with Live Data...");
            MineBitcoin(blockData);
        }
        else
        {
            Console.WriteLine("Failed to fetch blockchain data.");
        }
    }

    private static void MineBitcoin(dynamic blockData)
    {
        string previousBlockHash = blockData["prev_block"];
        string merkleRoot = "PlaceholderMerkleRoot"; // Replace with actual Merkle root if provided
        string timestamp = blockData["time"].ToString("X"); // Convert timestamp to hexadecimal
        string targetDifficulty = "0000000fffffffffffffffffffffffff"; // Simulated target

        while (true)
        {
            // Construct the block header
            string blockHeader = ConstructBlockHeader("20000000", previousBlockHash, merkleRoot, timestamp, nonce);

            // Compute the hash
            string hash = ComputeSHA256Hash(blockHeader);

            // Check if the hash meets difficulty criteria
            if (hash.CompareTo(targetDifficulty) <= 0)
            {
                Console.WriteLine($"Hash found: {hash} with nonce: {nonce}");
                break;
            }

            // Adjust nonce dynamically
            double hashHarmonic = AnalyzeHashHarmonic(hash);
            nonce = AdjustNonceBasedOnHarmonic(nonce, hashHarmonic);

            nonce++;
        }
    }

    private static async System.Threading.Tasks.Task<dynamic> FetchBlockDataFromAPI()
    {
        using (HttpClient client = new HttpClient())
        {
            try
            {
                HttpResponseMessage response = await client.GetAsync(apiUrl);
                response.EnsureSuccessStatusCode();

                string responseBody = await response.Content.ReadAsStringAsync();
                return JObject.Parse(responseBody);
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Error fetching data: {ex.Message}");
                return null;
            }
        }
    }

    private static string ConstructBlockHeader(string version, string prevHash, string merkle, string time, int nonce)
    {
        return $"{version}{prevHash}{merkle}{time}{nonce.ToString("X8")}";
    }

    private static string ComputeSHA256Hash(string input)
    {
        using (SHA256 sha256 = SHA256.Create())
        {
            byte[] hashBytes = sha256.ComputeHash(Encoding.UTF8.GetBytes(input));
            byte[] doubleHashBytes = sha256.ComputeHash(hashBytes);

            StringBuilder hash = new StringBuilder();
            foreach (byte b in doubleHashBytes)
            {
                hash.Append(b.ToString("x2"));
            }

            return hash.ToString();
        }
    }

    private static double AnalyzeHashHarmonic(string hash)
    {
        double harmonicSum = 0;
        foreach (char c in hash)
        {
            harmonicSum += c;
        }
        return harmonicSum / hash.Length;
    }

    private static int AdjustNonceBasedOnHarmonic(int nonce, double hashHarmonic)
    {
        if (hashHarmonic < 50)
        {
            nonce += 2;
        }
        else if (hashHarmonic > 100)
        {
            nonce -= 1;
        }
        return nonce;
    }
}
```

