            Console.WriteLine("Failed to fetch blockchain data.");
        }
    }

    private static async Task<JObject> FetchBlockDataFromAPI()
    {
        using (HttpClient client = new HttpClient())
        {
            try
            {
                string urlWithToken = string.IsNullOrEmpty(apiToken) ? apiBaseUrl : $"{apiBaseUrl}?token={apiToken}";
                HttpResponseMessage response = await client.GetAsync(urlWithToken);
                response.EnsureSuccessStatusCode();
                string responseBody = await response.Content.ReadAsStringAsync();
                return JObject.Parse(responseBody);
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Error fetching data: {ex.Message}");
                return new JObject
                {
                    ["prev_block"] = "00000000000000000000000000000000",
                    ["time"] = DateTimeOffset.UtcNow.ToUnixTimeSeconds()
                };
            }
        }
    }

    private static async Task MaxOutMining(dynamic blockData)
    {
        string previousBlockHash = blockData["prev_block"];
        string timestamp = blockData["time"].ToString("X");
        string targetDifficulty = "0000000fffffffffffffffffffffffff";
        string merkleRoot = "TestMerkleRoot";

        bool diminishingReturns = false;

        while (!diminishingReturns)
        {
            Console.WriteLine($"Starting grid size: {gridSize}");
            stopwatch.Restart();

            double hashRate = await Task.Run(() => MineIn3DParallel(previousBlockHash, timestamp, targetDifficulty, merkleRoot));

            stopwatch.Stop();
            Console.WriteLine($"Grid Size: {gridSize}, Hash Rate: {hashRate:F2} hashes/sec");

            if (hashRate > maxHashRate)
            {
                maxHashRate = hashRate;
                gridSize += 5;
            }
            else
            {
                diminishingReturns = true;
                Console.WriteLine("Diminishing returns detected. Tuning stopped.");
            }

            if (hashRate >= 0.35)
            {
                Console.WriteLine($"Target efficiency reached: {hashRate:F2} hashes/sec");
                break;
            }
        }
    }

    private static double MineIn3DParallel(string prevBlockHash, string timestamp, string targetDifficulty, string merkleRoot)
    {
        int totalHashes = 0;

        Parallel.For(0, gridSize, x =>
        {
            for (int y = 0; y < gridSize; y++)
            {
                for (int z = 0; z < gridSize; z++)
                {
                    int nonce = x * 1000 + y * 100 + z;
                    string blockHeader = ConstructBlockHeader("20000000", prevBlockHash, merkleRoot, timestamp, nonce);
                    string hash = ComputeSHA256Hash(blockHeader);

                    if (hash.CompareTo(targetDifficulty) <= 0)
                    {
                        Console.WriteLine($"Valid hash found: {hash} at (X={x}, Y={y}, Z={z}), Nonce: {nonce}");
                        return;
                    }

                    Interlocked.Increment(ref totalHashes);
                }
            }
        });

        double elapsedSeconds = stopwatch.Elapsed.TotalSeconds;
        return totalHashes / elapsedSeconds;
    }

    private static string ConstructBlockHeader(string version, string prevHash, string merkle, string time, int nonce)
    {
        return $"{version}{prevHash}{merkle}{time}{nonce.ToString("X8")}";
    }

    private static string ComputeSHA256Hash(string input)
    {
        using (SHA256 sha256 = SHA256.Create())
        {
            byte[] hashBytes = sha256.ComputeHash(Encoding.UTF8.GetBytes(input));
            byte[] doubleHashBytes = sha256.ComputeHash(hashBytes);

            StringBuilder hash = new StringBuilder();
            foreach (byte b in doubleHashBytes)
            {
                hash.Append(b.ToString("x2"));
            }

            return hash.ToString();
        }
    }
